examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    MonarchInlineNotice({{notices.0.message}}, tone: {{notices.0.tone|tone}})
    MonarchInlineNotice({{notices.1.message}}, tone: {{notices.1.tone|tone}})
    MonarchInlineNotice({{notices.2.message}}, title: {{notices.2.title}}, tone: {{notices.2.tone|tone}})
    MonarchInlineNotice({{notices.3.message}}, tone: {{notices.3.tone|tone}}, actionTitle: {{notices.3.action}}) {}
    MonarchInlineNotice({{notices.4.message}}, tone: {{notices.4.tone|tone}}, onDismiss: {})
}

examples.code:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    MonarchInlineNotice("Members sync from Rook ID every 15 minutes.", tone: .info)
    MonarchInlineNotice("Connected to the shared inbox.", tone: .success)
    MonarchInlineNotice("Emails from this domain may land in spam.", title: "Unverified.", tone: .warning)
    MonarchInlineNotice("Could not load comments.", tone: .danger, actionTitle: "Retry") {}
    MonarchInlineNotice("Draft restored from this device.", tone: .neutral, onDismiss: {})
}

MonarchInlineNotice(
    "Someone else edited this record.",
    title: "Conflict.",
    tone: .danger,
    actionTitle: "Reload"
) {
    reloads += 1
}
